output_text:
[
  {
    "id": "return_cart_to_top_left_bay",
    "text": "A shopper who uses the store cart must return it to the top-left cart bay before leaving.",
    "abstraction": {
      "state_properties": {
        "top_left_cart_bay": "at(0,1)"
      },
      "events": {
        "return_cart_to_bay": {
          "pre": {
            "and": [
              "top_left_cart_bay",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cartAt(0,1)"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "return_cart_to_bay"
    }
  },
  {
    "id": "take_cart_from_entrance",
    "text": "A shopper must take the entrance cart before doing the shopping trip.",
    "abstraction": {
      "state_properties": {
        "entrance_cart_station": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        }
      },
      "events": {
        "pickup_entrance_cart": {
          "pre": {
            "and": [
              "entrance_cart_station",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "pickup_entrance_cart"
    }
  },
  {
    "id": "no_exit_with_unreturned_cart",
    "text": "A shopper is forbidden to exit while still possessing the cart or while the cart is not parked in the return bay.",
    "abstraction": {
      "state_properties": {
        "cart_safely_returned": {
          "and": [
            "cartAt(0,1)",
            {
              "not": "hasCart"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          {
            "not": "cart_safely_returned"
          }
        ]
      }
    }
  },
  {
    "id": "only_leave_cart_at_bay",
    "text": "Putting the cart down is allowed only at the designated top-left return bay.",
    "abstraction": {
      "state_properties": {
        "top_left_cart_bay": "at(0,1)"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "LEAVE_CART",
          {
            "not": "top_left_cart_bay"
          }
        ]
      }
    }
  },
  {
    "id": "cart_required_for_item_pickup",
    "text": "Items must be picked up only while the shopper has the cart, not carried independently by hand.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "cartless_item_pickup": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartless_item_pickup"
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "A shopper should not carry groceries by hand during the trip.",
    "abstraction": {
      "state_properties": {
        "carrying_by_hand": "handFull"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "carrying_by_hand"
    }
  },
  {
    "id": "no_shopping_after_cart_return",
    "text": "Once the cart has been returned to the bay, the shopper may proceed to the exit but must not do further shopping interactions.",
    "abstraction": {
      "state_properties": {
        "cart_returned": {
          "and": [
            "cartAt(0,1)",
            {
              "not": "hasCart"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "cart_returned",
          "INTERACT"
        ]
      }
    }
  },
  {
    "id": "only_designated_primitive_interactions",
    "text": "The only permitted interactions are taking the entrance cart, picking up an item from a recognized shelf while holding the cart, and returning the cart at the top-left bay.",
    "abstraction": {
      "state_properties": {
        "recognized_item_shelf": {
          "or": [
            "at(1,3)",
            "at(2,4)",
            "at(3,2)",
            "at(3,4)",
            "at(5,2)",
            "at(5,4)",
            "at(6,2)",
            "at(6,4)"
          ]
        }
      },
      "events": {
        "take_entrance_cart": {
          "pre": {
            "and": [
              "at(1,5)",
              "cartAt(1,5)",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        },
        "shelf_item_pickup_with_cart": {
          "pre": {
            "and": [
              "recognized_item_shelf",
              "hasCart",
              "PICKUP_ITEM"
            ]
          },
          "post": null
        },
        "bay_cart_return": {
          "pre": {
            "and": [
              "at(0,1)",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cartAt(0,1)"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          {
            "not": {
              "or": [
                "take_entrance_cart",
                "shelf_item_pickup_with_cart",
                "bay_cart_return"
              ]
            }
          }
        ]
      }
    }
  }
]
